import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Laptop, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Zap } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState(''); // We'll use this as "Login ID" for MRs
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // Track automated runs in the current session to avoid log spamming
  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { setUser(session); setView('DASHBOARD'); }

    // Start Global Automation Background Task
    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
                const currentUser = storageService.getCurrentUser();
                if (currentUser?.hospitalId === hosp.id && currentUser.role === 'ADMIN') {
                  showFeedback(`Scheduled lottery for ${sess} executed automatically!`, 'success');
                }
              } else {
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 15000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: existing.id, 
          fullName: existing.fullName, 
          role: 'MR', 
          companyName: existing.companyName, 
          loginId: existing.loginId,
          mobileNumber: existing.mobileNumber 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center">
                     <Briefcase className="h-3 w-3 mb-1" /> Pharma Admin
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center">
                     <Crown className="h-3 w-3 mb-1" /> Super Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Login User ID' : 'Login ID / Mobile'}</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "e.g. john_mr" : role === 'SUPER_ADMIN' ? "root" : "Admin ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30 hover:grayscale-0 hover:opacity-100 transition-all cursor-default">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-white/10 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20">
                <HospitalIcon className="h-3.5 w-3.5 text-indigo-100" />
                <span className="text-xs font-black text-white tracking-tighter">MedPass Technology</span>
              </div>
            </div>
            <p className="text-[9px] font-bold text-indigo-200 uppercase tracking-widest opacity-60">Enterprise Compliance Grid</p>
          </div>

          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user.role === 'SUPER_ADMIN' ? 'Root Authority' : user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN' | 'COMPANY_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  email?: string;
  companyName: string; 
  mrId: string;
  loginId: string;
  mobileNumber: string;
  password?: string; 
  identificationNumber: string;
  slcpiId?: string;
  slcpiPhoto?: string;
  slcpiExpiry?: string;
  status: MRStatus;
  createdAt: string;
}

export interface Gate {
  id: string;
  name: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; 
  sessionWindows: Record<string, { start: string; end: string }>; 
  isActive: boolean;
  mobileNumber?: string;
  email?: string;
  address?: string;
  autoLotteryEnabled?: Record<string, boolean>;
  autoLotteryTimes?: Record<string, string>;
  gates?: Gate[];
}

export interface HospitalUser {
  id: string;
  hospitalId: string;
  mobileNumber: string; 
  password: string;     
  role: 'ADMIN' | 'SECURITY';
  fullName: string;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
  entryTime?: string;
  entryGateId?: string;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
  companyCode: string; 
  adminMobile: string; 
  adminPassword: string; 
  isActive: boolean;
  address?: string;
  contactNumber?: string;
  financeEmail?: string;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
  gateId?: string;
}

export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  loginId?: string;
  hospitalId?: string; 
  companyId?: string; 
  companyName?: string; 
}

import React, { useState, useEffect, useMemo } from 'react';
import { CheckCircle2, XCircle, Clock, MapPin, ShieldAlert, ArrowLeft, Loader2, Hospital as HospitalIcon } from 'lucide-react';
import { storageService } from '../services/storageService';
import { IssuedPass, Hospital, MedicalRep, SessionType } from '../types';

interface GateEntryViewProps {
  hospitalId: string;
  gateId: string;
  user: MedicalRep;
  onClose: () => void;
}

const GateEntryView: React.FC<GateEntryViewProps> = ({ hospitalId, gateId, user, onClose }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [countdown, setCountdown] = useState(120); // 2 minute validity countdown
  const [verificationResult, setVerificationResult] = useState<{
    status: 'loading' | 'success' | 'error';
    message?: string;
    pass?: IssuedPass;
    hospital?: Hospital;
  }>({ status: 'loading' });

  // Update clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Update countdown
  useEffect(() => {
    if (verificationResult.status === 'success' && countdown > 0) {
      const timer = setInterval(() => setCountdown(prev => prev - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [verificationResult.status, countdown]);

  useEffect(() => {
    const validateEntry = () => {
      const today = new Date().toISOString().split('T')[0];
      const timeStr = `${currentTime.getHours().toString().padStart(2, '0')}:${currentTime.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      const hosp = hospitals.find(h => h.id === hospitalId);

      if (!hosp) {
        setVerificationResult({ status: 'error', message: 'Invalid Hospital Code' });
        return;
      }

      if (!hosp.isActive) {
        setVerificationResult({ status: 'error', message: 'Facility Node Offline', hospital: hosp });
        return;
      }

      const allPasses = storageService.getPasses();
      const validPass = allPasses.find(p => 
        p.mrId === user.id && 
        p.hospitalId === hospitalId && 
        p.passDate === today &&
        p.entryStatus === 'not_entered'
      );

      if (!validPass) {
        // Check if already used today
        const usedPass = allPasses.find(p => 
          p.mrId === user.id && 
          p.hospitalId === hospitalId && 
          p.passDate === today &&
          p.entryStatus === 'entered'
        );

        if (usedPass) {
          setVerificationResult({ status: 'error', message: 'Pass Already Used Today', hospital: hosp });
        } else {
          setVerificationResult({ status: 'error', message: 'No Valid Pass Found for Today', hospital: hosp });
        }
        return;
      }

      // Session Window Validation
      const window = hosp.sessionWindows?.[validPass.session];
      if (!window) {
        setVerificationResult({ status: 'error', message: 'Session Configuration Error', hospital: hosp });
        return;
      }

      if (timeStr < window.start || timeStr > window.end) {
        setVerificationResult({ 
          status: 'error', 
          message: `Session Out of Window (${window.start} - ${window.end})`, 
          hospital: hosp 
        });
        return;
      }

      // Success - Mark as used in storage immediately
      const updatedPasses = allPasses.map(p => 
        p.id === validPass.id 
          ? { ...p, entryStatus: 'entered' as const, entryTime: new Date().toISOString(), entryGateId: gateId } 
          : p
      );
      storageService.savePasses(updatedPasses);

      // Add to logs
      const log = {
        id: Math.random().toString(36).substr(2, 9),
        issuedPassId: validPass.id,
        entryTime: new Date().toISOString(),
        verifiedBy: 'System-Auto',
        gateId: gateId
      };
      storageService.saveLogs([...storageService.getLogs(), log]);

      setVerificationResult({ status: 'success', pass: validPass, hospital: hosp });
    };

    // Simulate small processing delay for UX
    const timer = setTimeout(validateEntry, 1200);
    return () => clearTimeout(timer);
  }, []);

  if (verificationResult.status === 'loading') {
    return (
      <div className="fixed inset-0 z-[300] bg-slate-900 flex flex-col items-center justify-center p-6 text-white text-center">
        <Loader2 className="h-12 w-12 text-indigo-400 animate-spin mb-6" />
        <h2 className="text-xl font-black tracking-tight uppercase">Authenticating Pass...</h2>
        <p className="text-slate-400 text-sm mt-2">Checking real-time facility ledger</p>
      </div>
    );
  }

  if (verificationResult.status === 'error') {
    return (
      <div className="fixed inset-0 z-[300] bg-rose-600 flex flex-col items-center justify-center p-8 text-white text-center animate-in fade-in duration-300">
        <div className="bg-white/20 p-6 rounded-full mb-8 backdrop-blur-md">
          <XCircle className="h-20 w-20 text-white" />
        </div>
        <h1 className="text-4xl font-black mb-4 uppercase tracking-tighter">Entry Rejected</h1>
        <div className="bg-black/20 backdrop-blur-sm px-6 py-4 rounded-3xl mb-12">
          <p className="text-xl font-bold">{verificationResult.message}</p>
        </div>

        <div className="space-y-6 w-full max-w-sm">
          <div className="flex flex-col items-center gap-1 opacity-80">
            <HospitalIcon className="h-5 w-5" />
            <p className="font-black text-sm uppercase">{verificationResult.hospital?.name || 'Unknown Facility'}</p>
          </div>
          <button 
            onClick={onClose}
            className="w-full bg-white text-rose-600 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl active:scale-95 transition-all"
          >
            Return to Dashboard
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[300] bg-emerald-600 flex flex-col overflow-hidden text-white animate-in fade-in duration-500">
      {/* Animated background to prevent screenshots */}
      <div className="absolute inset-0 opacity-10 pointer-events-none">
        <div className="absolute inset-0" style={{ backgroundImage: 'radial-gradient(circle at 2px 2px, white 1px, transparent 0)', backgroundSize: '40px 40px' }} />
        <div className="absolute inset-0 animate-pulse bg-emerald-400" />
      </div>

      <div className="relative z-10 flex flex-col h-full">
        {/* Top Header */}
        <div className="p-8 pt-12 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-2 bg-white/20 backdrop-blur-md px-3 py-1 rounded-full w-fit mb-2">
              <div className="w-2 h-2 rounded-full bg-white animate-ping" />
              <span className="text-[10px] font-black uppercase tracking-widest">Live Verified</span>
            </div>
            <h1 className="text-4xl font-black tracking-tighter uppercase leading-none">Entry Approved</h1>
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 hover:bg-white/20 rounded-2xl transition-all">
            <ArrowLeft className="h-6 w-6" />
          </button>
        </div>

        {/* Center Content */}
        <div className="flex-1 flex flex-col items-center justify-center p-8">
          <div className="bg-white p-6 rounded-[3rem] shadow-2xl mb-8 border-4 border-emerald-400 animate-in zoom-in duration-700">
            <CheckCircle2 className="h-32 w-32 text-emerald-600" />
          </div>

          <div className="text-center space-y-2 mb-10">
            <p className="text-emerald-100 font-bold uppercase tracking-widest text-xs">Medical Representative</p>
            <h2 className="text-3xl font-black leading-tight">{user.fullName}</h2>
            <p className="text-lg font-bold opacity-80">{user.companyName}</p>
          </div>

          <div className="grid grid-cols-2 gap-4 w-full max-w-md">
            <div className="bg-white/10 backdrop-blur-md p-4 rounded-3xl border border-white/20 text-center">
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-200 mb-1">Session</p>
              <p className="text-xl font-black">{verificationResult.pass?.session.replace('_', ' ')}</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md p-4 rounded-3xl border border-white/20 text-center">
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-200 mb-1">Gate ID</p>
              <p className="text-xl font-black">{gateId || '01'}</p>
            </div>
          </div>
        </div>

        {/* Bottom Safety Info */}
        <div className="p-8 bg-black/10 backdrop-blur-lg border-t border-white/10">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <Clock className="h-8 w-8 text-emerald-300" />
              <div>
                <p className="text-2xl font-black font-mono tracking-widest">
                  {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })}
                </p>
                <p className="text-[10px] font-black uppercase opacity-60">Verification Timestamp</p>
              </div>
            </div>
            <div className="text-right">
              <p className={`text-2xl font-black font-mono ${countdown < 30 ? 'text-amber-300 animate-pulse' : 'text-white'}`}>
                {Math.floor(countdown / 60)}:{(countdown % 60).toString().padStart(2, '0')}
              </p>
              <p className="text-[10px] font-black uppercase opacity-60">Validity Countdown</p>
            </div>
          </div>

          <div className="flex items-center gap-3 p-4 bg-emerald-700/50 rounded-2xl border border-white/10">
            <ShieldAlert className="h-5 w-5 text-emerald-300" />
            <p className="text-[10px] font-bold leading-relaxed text-emerald-100 uppercase">
              Show this green screen to the guard. Do not close this screen until you have cleared the gate checkpoint.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GateEntryView;

import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import GateEntryView from './components/GateEntryView';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Laptop, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Zap, QrCode } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD' | 'GATE_VERIFY'>('LOGIN');
  const [gateParams, setGateParams] = useState<{ hospitalId: string; gateId: string } | null>(null);
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState(''); 
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    // Detect Gate Entry URL Parameters
    const params = new URLSearchParams(window.location.search);
    const hospId = params.get('hospital_id');
    const gateId = params.get('gate_id') || '01';

    if (hospId) {
      setGateParams({ hospitalId: hospId, gateId });
    }

    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      if (hospId && session.role === 'MR') {
        setView('GATE_VERIFY');
      } else {
        setView('DASHBOARD'); 
      }
    }

    // Start Global Automation Background Task
    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
              } else {
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 15000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: existing.id, 
          fullName: existing.fullName, 
          role: 'MR', 
          companyName: existing.companyName, 
          loginId: existing.loginId,
          mobileNumber: existing.mobileNumber 
        };
        storageService.setCurrentUser(u); 
        setUser(u); 

        if (gateParams) {
          setView('GATE_VERIFY');
        } else {
          setView('DASHBOARD');
        }
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);
      if (found && found.password === password) {
        const u: AuthUser = { 
          id: found.id,
          role: found.role, 
          fullName: found.fullName, 
          hospitalId: found.hospitalId,
          mobileNumber: found.mobileNumber
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
      } else {
        showFeedback("Invalid hospital staff credentials.", 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'GATE_VERIFY' && gateParams && user) {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <GateEntryView 
          hospitalId={gateParams.hospitalId} 
          gateId={gateParams.gateId} 
          user={user} 
          onClose={() => {
            // Clean URL params when returning to dashboard
            const url = new URL(window.location.href);
            url.search = '';
            window.history.replaceState({}, '', url.toString());
            setGateParams(null);
            setView('DASHBOARD');
          }} 
        />
        {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
      </FeedbackContext.Provider>
    );
  }

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
              {gateParams && (
                <div className="mt-4 bg-amber-50 border border-amber-200 p-3 rounded-xl flex items-center gap-2 text-left">
                  <QrCode className="h-5 w-5 text-amber-500 shrink-0" />
                  <p className="text-[10px] font-bold text-amber-800 uppercase leading-tight">Gate Entry Protocol Detected. Please login to verify your pass.</p>
                </div>
              )}
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Login User ID' : 'Login ID / Mobile'}</label>
                  <input type="text" value={mobile} onChange={e => setMobile(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30 hover:grayscale-0 hover:opacity-100 transition-all cursor-default">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-white/10 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20">
                <HospitalIcon className="h-3.5 w-3.5 text-indigo-100" />
                <span className="text-xs font-black text-white tracking-tighter">MedPass Technology</span>
              </div>
            </div>
          </div>

          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user.role === 'SUPER_ADMIN' ? 'Root Authority' : user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Scan
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })));
    setAiInsight(insight);
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;

    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const handleSimulateScan = (hId: string) => {
    // In a real app, scanning the QR opens: https://app.com/?hospital_id=XYZ&gate_id=01
    // We simulate this by updating the browser URL
    const url = new URL(window.location.href);
    url.searchParams.set('hospital_id', hId);
    url.searchParams.set('gate_id', 'G-01');
    window.location.href = url.toString();
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="flex justify-between items-start mb-4">
                    <p className="font-black text-slate-800 text-lg">{h.name}</p>
                    <button 
                      onClick={() => handleSimulateScan(h.id)}
                      className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2 text-[10px] font-black uppercase"
                    >
                      <Scan className="h-3 w-3" /> Scan Gate
                    </button>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={loading}
                            onClick={() => handleApply(h.id, sess)}
                            className="w-full py-3 px-4 bg-white border border-slate-200 hover:border-indigo-400 rounded-xl text-xs font-black flex items-center justify-between transition-all"
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4 text-amber-500" /> : <Moon className="h-4 w-4 text-indigo-400" />}
                              {sess}
                            </span>
                            <PlusCircle className="h-4 w-4 text-indigo-600" />
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {h.sessionWindows?.[sess]?.start} - {h.sessionWindows?.[sess]?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">WINDOW OPEN</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <QrCode className="h-5 w-5 text-indigo-500" /> Active Passes
            </h3>
            <div className="space-y-4">
              {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).map(p => (
                <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-[10px] font-black uppercase text-indigo-600">{p.session}</span>
                    <span className="text-[10px] font-bold text-slate-400">{p.passDate}</span>
                  </div>
                  <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                  <div className="bg-white p-4 rounded-xl flex flex-col items-center gap-3">
                    <QrCode className="h-20 w-20 text-indigo-900" />
                    <p className="text-[9px] font-black text-slate-400 tracking-widest uppercase">Verification Code: {p.id}</p>
                  </div>
                </div>
              ))}
              {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).length === 0 && (
                <div className="text-center py-12 text-slate-400 italic text-xs">No active passes for today.</div>
              )}
            </div>
          </section>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">Hospital Directory</h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {hospitals.filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase())).map(h => (
              <div key={h.id} className="p-5 border border-slate-100 bg-slate-50 rounded-2xl flex flex-col justify-between">
                <div>
