interface GateEntryViewProps {
  hospitalId: string;
  gateId: string;
  user: MedicalRep;
  onClose: () => void;
}

const GateEntryView: React.FC<GateEntryViewProps> = ({ hospitalId, gateId, user, onClose }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [countdown, setCountdown] = useState(120); 
  const [verificationResult, setVerificationResult] = useState<{
    status: 'loading' | 'success' | 'error';
    message?: string;
    pass?: IssuedPass;
    hospital?: Hospital;
  }>({ status: 'loading' });

  // Update clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Update countdown
  useEffect(() => {
    if (verificationResult.status === 'success' && countdown > 0) {
      const timer = setInterval(() => setCountdown(prev => prev - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [verificationResult.status, countdown]);

  useEffect(() => {
    const validateEntry = () => {
      const today = new Date().toISOString().split('T')[0];
      const now = new Date();
      const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      const hosp = hospitals.find(h => h.id === hospitalId);

      if (!hosp) {
        setVerificationResult({ status: 'error', message: 'Hospital Record Not Found' });
        return;
      }

      if (!hosp.isActive) {
        setVerificationResult({ status: 'error', message: 'Facility Offline', hospital: hosp });
        return;
      }

      const allPasses = storageService.getPasses();

      // Validation A: Valid Pass Exists
      // Check in hospital_passes: mr_id = logged-in MR, hospital_id = from QR, pass_date = today, status = APPROVED, entry_status = NOT_USED
      const validPass = allPasses.find(p => 
        p.mrId === user.id && 
        p.hospitalId === hospitalId && 
        p.passDate === today &&
        p.status === 'APPROVED' &&
        p.entryStatus === 'NOT_USED'
      );

      if (!validPass) {
        const usedPass = allPasses.find(p => 
          p.mrId === user.id && 
          p.hospitalId === hospitalId && 
          p.passDate === today &&
          p.entryStatus === 'USED'
        );

        if (usedPass) {
          setVerificationResult({ status: 'error', message: 'Pass Already Used', hospital: hosp });
        } else {
          setVerificationResult({ status: 'error', message: 'No Valid Pass for Today', hospital: hosp });
        }
        return;
      }

      // Validation B: Session Time Check
      const window = hosp.sessionWindows?.[validPass.session];
      if (!window) {
        setVerificationResult({ status: 'error', message: 'Session Config Error', hospital: hosp });
        return;
      }

      if (timeStr < window.start || timeStr > window.end) {
        setVerificationResult({ 
          status: 'error', 
          message: `Session Not Active (${window.start} - ${window.end})`, 
          hospital: hosp 
        });
        return;
      }

      // Success: mark as USED
      const updatedPasses = allPasses.map(p => 
        p.id === validPass.id 
          ? { ...p, entryStatus: 'USED' as const, entryTime: new Date().toISOString(), entryGateId: gateId } 
          : p
      );
      storageService.savePasses(updatedPasses);

      // Create log
      const log = {
        id: Math.random().toString(36).substr(2, 9),
        issuedPassId: validPass.id,
        entryTime: new Date().toISOString(),
        verifiedBy: 'System-Auto',
        gateId: gateId
      };
      storageService.saveLogs([...storageService.getLogs(), log]);

      setVerificationResult({ status: 'success', pass: validPass, hospital: hosp });
    };

    const timer = setTimeout(validateEntry, 1500);
    return () => clearTimeout(timer);
  }, [hospitalId, gateId, user.id]);

  if (verificationResult.status === 'loading') {
    return (
      <div className="fixed inset-0 z-[300] bg-slate-900 flex flex-col items-center justify-center p-6 text-white text-center">
        <Loader2 className="h-16 w-16 text-indigo-400 animate-spin mb-8" />
        <h2 className="text-2xl font-black tracking-tight uppercase">Verifying Pass...</h2>
        <p className="text-slate-400 text-sm mt-3">Validating gate protocol with hospital server</p>
      </div>
    );
  }

  if (verificationResult.status === 'error') {
    return (
      <div className="fixed inset-0 z-[300] bg-rose-600 flex flex-col items-center justify-center p-8 text-white text-center animate-in fade-in duration-300">
        <div className="bg-white/20 p-8 rounded-full mb-10 backdrop-blur-md border border-white/30">
          <XCircle className="h-24 w-24 text-white" />
        </div>
        <h1 className="text-5xl font-black mb-6 uppercase tracking-tighter">Entry Rejected</h1>
        <div className="bg-black/20 backdrop-blur-sm px-8 py-6 rounded-3xl mb-12 border border-white/10">
          <p className="text-2xl font-bold">{verificationResult.message}</p>
        </div>

        <div className="space-y-8 w-full max-w-sm">
          <div className="flex flex-col items-center gap-2 opacity-80 bg-black/10 p-4 rounded-2xl">
            <HospitalIcon className="h-6 w-6" />
            <p className="font-black text-sm uppercase tracking-widest">{verificationResult.hospital?.name || 'Unknown Facility'}</p>
          </div>
          <button 
            onClick={onClose}
            className="w-full bg-white text-rose-600 py-5 rounded-2xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all"
          >
            Back to Dashboard
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[300] bg-emerald-600 flex flex-col overflow-hidden text-white animate-in fade-in duration-500">
      {/* Anti-screenshot animated background */}
      <div className="absolute inset-0 opacity-15 pointer-events-none">
        <div className="absolute inset-0" style={{ backgroundImage: 'radial-gradient(circle at 2px 2px, white 1px, transparent 0)', backgroundSize: '40px 40px' }} />
        <div className="absolute inset-0 animate-pulse bg-emerald-400 duration-[2000ms]" />
        <div className="absolute top-0 left-0 w-full h-full animate-[spin_60s_linear_infinite]" style={{ backgroundImage: 'conic-gradient(from 0deg, transparent, rgba(255,255,255,0.1), transparent)' }} />
      </div>

      <div className="relative z-10 flex flex-col h-full">
        {/* Success Header */}
        <div className="p-8 pt-16 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-2 bg-white/20 backdrop-blur-md px-4 py-1.5 rounded-full w-fit mb-4 border border-white/30">
              <div className="w-2.5 h-2.5 rounded-full bg-white animate-ping" />
              <span className="text-[10px] font-black uppercase tracking-widest">Live Confirmation</span>
            </div>
            <h1 className="text-5xl font-black tracking-tighter uppercase leading-none mb-2">Entry Approved</h1>
            <p className="text-emerald-100 font-bold text-sm">Valid for {verificationResult.hospital?.name}</p>
          </div>
        </div>

        {/* Center Verification Content */}
        <div className="flex-1 flex flex-col items-center justify-center p-8">
          <div className="bg-white p-8 rounded-[4rem] shadow-2xl mb-10 border-[6px] border-emerald-400 animate-in zoom-in duration-700 shadow-emerald-900/40">
            <CheckCircle2 className="h-40 w-40 text-emerald-600" />
          </div>

          <div className="text-center space-y-3 mb-12">
            <p className="text-emerald-100 font-black uppercase tracking-[0.3em] text-xs">Medical Representative</p>
            <h2 className="text-4xl font-black leading-tight tracking-tight">{user.fullName}</h2>
            <div className="inline-block px-4 py-1 bg-white/10 rounded-lg backdrop-blur-sm border border-white/10">
               <p className="text-xl font-bold text-emerald-50">{user.companyName}</p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-5 w-full max-w-md">
            <div className="bg-white/10 backdrop-blur-md p-5 rounded-3xl border border-white/20 text-center shadow-lg">
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-200 mb-1.5">Session Type</p>
              <p className="text-2xl font-black">{verificationResult.pass?.session.replace('_', ' ')}</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md p-5 rounded-3xl border border-white/20 text-center shadow-lg">
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-200 mb-1.5">Hospital Gate</p>
              <p className="text-2xl font-black">{gateId}</p>
            </div>
          </div>
        </div>

        {/* Security Footer */}
        <div className="p-8 bg-black/20 backdrop-blur-2xl border-t border-white/20 rounded-t-[3rem] shadow-[0_-20px_50px_rgba(0,0,0,0.1)]">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
              <div className="bg-emerald-500/20 p-3 rounded-2xl">
                <Clock className="h-10 w-10 text-emerald-300" />
              </div>
              <div>
                <p className="text-3xl font-black font-mono tracking-widest leading-none mb-1">
                  {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })}
                </p>
                <p className="text-[10px] font-black uppercase tracking-widest opacity-60">System Synchronized Time</p>
              </div>
            </div>
            <div className="text-right">
              <p className={`text-3xl font-black font-mono leading-none mb-1 ${countdown < 30 ? 'text-rose-400 animate-pulse' : 'text-white'}`}>
                {Math.floor(countdown / 60)}:{(countdown % 60).toString().padStart(2, '0')}
              </p>
              <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Screen Validity</p>
            </div>
          </div>

          <div className="flex items-start gap-4 p-5 bg-emerald-800/40 rounded-[2rem] border border-white/10">
            <ShieldAlert className="h-6 w-6 text-emerald-300 shrink-0 mt-1" />
