                        </button>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest px-1">Window: {h.sessionWindows?.[sess]?.start} - {h.sessionWindows?.[sess]?.end}</p>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
