                       <Scan className="h-10 w-10 text-slate-300 mb-2" />
                       <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-tight">Scan Permanent Hospital QR<br/>to Verify Entry</p>
                    </div>
                  </div>
                </div>
              ))}
              {passes.filter(p => p.entryStatus === 'NOT_USED' && p.passDate === new Date().toISOString().split('T')[0]).length === 0 && (
                <div className="text-center py-16 text-slate-400 italic text-xs border border-dashed border-slate-200 rounded-3xl">
                  No active passes for today.
                </div>
              )}
            </div>
          </section>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in fade-in">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-xl font-bold">Hospital Directory</h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-bold"
              />
