           <div className="grid grid-cols-2 gap-4">
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Login ID</p><p className="font-bold text-slate-800">{user.loginId}</p></div>
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Mobile</p><p className="font-bold text-slate-800">{user.mobileNumber}</p></div>
           </div>
        </section>
      )}
    </div>
  );
};

