import React, { useState, useEffect } from 'react';
import { CheckCircle2, XCircle, Clock, ShieldAlert, ArrowLeft, Loader2, Hospital as HospitalIcon, Scan } from 'lucide-react';
import { storageService } from '../services/storageService';
import { IssuedPass, Hospital, MedicalRep } from '../types';

interface GateEntryViewProps {
  hospitalId: string;
  gateId: string;
  user: MedicalRep;
  onClose: () => void;
}

const GateEntryView: React.FC<GateEntryViewProps> = ({ hospitalId, gateId, user, onClose }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [countdown, setCountdown] = useState(120); 
  const [verificationResult, setVerificationResult] = useState<{
    status: 'loading' | 'success' | 'error';
    message?: string;
    pass?: IssuedPass;
    hospital?: Hospital;
  }>({ status: 'loading' });

  // Update clock every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Validity countdown (2 minutes)
  useEffect(() => {
    if (verificationResult.status === 'success' && countdown > 0) {
      const timer = setInterval(() => setCountdown(prev => prev - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [verificationResult.status, countdown]);

  useEffect(() => {
    const validateEntry = () => {
      const today = new Date().toISOString().split('T')[0];
      const now = new Date();
      const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      const hosp = hospitals.find(h => h.id === hospitalId);

      if (!hosp) {
        setVerificationResult({ status: 'error', message: 'Hospital Record Not Found' });
        return;
      }

      if (!hosp.isActive) {
        setVerificationResult({ status: 'error', message: 'Facility Node Offline', hospital: hosp });
        return;
      }

      const allPasses = storageService.getPasses();

      /**
       * BACKEND VALIDATION LOGIC
       * A. Valid Pass Exists: status = APPROVED, entry_status = NOT_USED, pass_date = today
       */
      const validPass = allPasses.find(p => 
        p.mrId === user.id && 
        p.hospitalId === hospitalId && 
        p.passDate === today &&
        p.status === 'APPROVED' &&
        p.entryStatus === 'NOT_USED'
      );

      if (!validPass) {
        const usedPass = allPasses.find(p => 
          p.mrId === user.id && 
          p.hospitalId === hospitalId && 
          p.passDate === today &&
          p.entryStatus === 'USED'
        );

        if (usedPass) {
          setVerificationResult({ status: 'error', message: 'Pass Already Used Today', hospital: hosp });
        } else {
          setVerificationResult({ status: 'error', message: 'No Approved Pass Found for Today', hospital: hosp });
        }
        return;
      }

      /**
       * B. Session Time Check
       * Get session_type from pass record. Check if current time is between start_time and end_time.
       */
      const window = hosp.sessionWindows?.[validPass.session];
      if (!window) {
        setVerificationResult({ status: 'error', message: 'Session Configuration Error', hospital: hosp });
        return;
      }

      if (timeStr < window.start || timeStr > window.end) {
        setVerificationResult({ 
          status: 'error', 
          message: `Session Out of Window (${window.start} - ${window.end})`, 
          hospital: hosp 
        });
        return;
      }

      // APPROVE ENTRY - Update record
      const updatedPasses = allPasses.map(p => 
        p.id === validPass.id 
          ? { ...p, entryStatus: 'USED' as const, entryTime: new Date().toISOString(), entryGateId: gateId } 
          : p
      );
      storageService.savePasses(updatedPasses);

      // Log for auditing
      const log = {
        id: Math.random().toString(36).substr(2, 9),
        issuedPassId: validPass.id,
        entryTime: new Date().toISOString(),
        verifiedBy: 'System-Auto-Gate',
        gateId: gateId
      };
      storageService.saveLogs([...storageService.getLogs(), log]);

      setVerificationResult({ status: 'success', pass: { ...validPass, entryStatus: 'USED' }, hospital: hosp });
    };

    // UX delay to simulate network authentication
    const timer = setTimeout(validateEntry, 1800);
    return () => clearTimeout(timer);
  }, [hospitalId, gateId, user.id]);

  if (verificationResult.status === 'loading') {
    return (
      <div className="fixed inset-0 z-[300] bg-slate-900 flex flex-col items-center justify-center p-6 text-white text-center">
        <Loader2 className="h-16 w-16 text-indigo-400 animate-spin mb-8" />
        <h2 className="text-2xl font-black tracking-tight uppercase">Authenticating Terminal...</h2>
        <p className="text-slate-400 text-sm mt-3">Establishing secure handshake with gate {gateId}</p>
      </div>
    );
  }

  if (verificationResult.status === 'error') {
    return (
      <div className="fixed inset-0 z-[300] bg-rose-600 flex flex-col items-center justify-center p-8 text-white text-center animate-in fade-in duration-300">
        <div className="bg-white/20 p-8 rounded-full mb-10 backdrop-blur-md border border-white/30">
          <XCircle className="h-24 w-24 text-white" />
        </div>
        <h1 className="text-5xl font-black mb-6 uppercase tracking-tighter">Access Denied</h1>
        <div className="bg-black/20 backdrop-blur-sm px-8 py-6 rounded-3xl mb-12 border border-white/10">
          <p className="text-2xl font-bold">{verificationResult.message}</p>
        </div>

        <div className="space-y-8 w-full max-w-sm">
          <div className="flex flex-col items-center gap-2 opacity-80 bg-black/10 p-4 rounded-2xl">
            <HospitalIcon className="h-6 w-6" />
            <p className="font-black text-sm uppercase tracking-widest">{verificationResult.hospital?.name || 'Unknown Facility'}</p>
          </div>
          <button 
            onClick={onClose}
            className="w-full bg-white text-rose-600 py-5 rounded-2xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all"
          >
            Back to Dashboard
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[300] bg-emerald-600 flex flex-col overflow-hidden text-white animate-in fade-in duration-500">
      {/* Animated background anti-screenshot measure */}
      <div className="absolute inset-0 opacity-20 pointer-events-none">
        <div className="absolute inset-0" style={{ backgroundImage: 'radial-gradient(circle at 2px 2px, white 1px, transparent 0)', backgroundSize: '40px 40px' }} />
        <div className="absolute inset-0 animate-pulse bg-emerald-400 duration-[1500ms]" />
        <div className="absolute top-0 left-0 w-full h-full animate-[spin_40s_linear_infinite] opacity-50" style={{ backgroundImage: 'conic-gradient(from 0deg, transparent, rgba(255,255,255,0.2), transparent)' }} />
      </div>

      <div className="relative z-10 flex flex-col h-full">
        {/* Verification Status Header */}
        <div className="p-8 pt-16 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-2 bg-white/30 backdrop-blur-md px-4 py-1.5 rounded-full w-fit mb-4 border border-white/40 shadow-sm">
              <div className="w-2.5 h-2.5 rounded-full bg-white animate-ping" />
              <span className="text-[10px] font-black uppercase tracking-widest">Entry Validated</span>
            </div>
            <h1 className="text-5xl font-black tracking-tighter uppercase leading-none mb-2">Approved</h1>
            <p className="text-emerald-100 font-bold text-sm opacity-90">{verificationResult.hospital?.name}</p>
          </div>
        </div>

        {/* Success Branding */}
        <div className="flex-1 flex flex-col items-center justify-center p-8">
          <div className="bg-white p-10 rounded-[4.5rem] shadow-2xl mb-10 border-[8px] border-emerald-400 animate-in zoom-in duration-700 shadow-emerald-900/40">
            <CheckCircle2 className="h-44 w-44 text-emerald-600" />
          </div>

          <div className="text-center space-y-4 mb-12">
            <p className="text-emerald-100 font-black uppercase tracking-[0.4em] text-[10px]">Medical Representative</p>
            <h2 className="text-4xl font-black leading-tight tracking-tight">{user.fullName}</h2>
            <div className="inline-block px-5 py-1.5 bg-white/20 rounded-xl backdrop-blur-md border border-white/20 shadow-inner">
               <p className="text-xl font-bold text-white">{user.companyName}</p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-5 w-full max-w-md">
            <div className="bg-white/20 backdrop-blur-xl p-6 rounded-[2.5rem] border border-white/20 text-center shadow-xl">
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-100 mb-2">Session</p>
              <p className="text-2xl font-black">{verificationResult.pass?.session.replace('_', ' ')}</p>
            </div>
            <div className="bg-white/20 backdrop-blur-xl p-6 rounded-[2.5rem] border border-white/20 text-center shadow-xl">
              <p className="text-[10px] font-black uppercase tracking-widest text-emerald-100 mb-2">Terminal</p>
              <p className="text-2xl font-black">{gateId || '01'}</p>
            </div>
          </div>
        </div>

        {/* Time-Sensitive Security Footer */}
        <div className="p-8 bg-black/30 backdrop-blur-3xl border-t border-white/20 rounded-t-[4rem] shadow-[0_-30px_60px_rgba(0,0,0,0.2)]">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-5">
              <div className="bg-emerald-500/30 p-4 rounded-2xl border border-white/10">
                <Clock className="h-10 w-10 text-emerald-200" />
              </div>
