import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import GateEntryView from './components/GateEntryView';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Laptop, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Zap, QrCode, Scan } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD' | 'GATE_ENTRY'>('LOGIN');
  const [gateParams, setGateParams] = useState<{ hospitalId: string; gateId: string } | null>(null);
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState(''); 
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    // Detect permanent QR scan from URL (e.g. ?hospital_id=h1&gate_id=1)
    const params = new URLSearchParams(window.location.search);
    const hId = params.get('hospital_id');
    const gId = params.get('gate_id');

    if (hId && gId) {
      setGateParams({ hospitalId: hId, gateId: gId });
    }

    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      if (hId && gId && session.role === 'MR') {
        setView('GATE_ENTRY');
      } else {
        setView('DASHBOARD'); 
      }
    }

    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;
        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          if (hosp.autoLotteryEnabled?.[sess] && hosp.autoLotteryTimes?.[sess] === currentTimeStr) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              lotteryService.runLottery(hosp.id, sess);
              autoRunLogs.current.add(logKey);
            }
          }
        });
      });
    }, 30000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    let foundUser: AuthUser | null = null;

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing && existing.password === password) {
        if (existing.status === 'suspended') {
          showFeedback("Account suspended.", 'error'); return;
        }
        foundUser = { 
          id: existing.id, fullName: existing.fullName, role: 'MR', 
          companyName: existing.companyName, loginId: existing.loginId, mobileNumber: existing.mobileNumber 
        };
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile && c.adminPassword === password);
      if (found) foundUser = { id: found.id, role: 'COMPANY_ADMIN', fullName: `${found.name} Admin`, companyId: found.id };
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.password === password && u.role === role);
      if (found) foundUser = { id: found.id, role: found.role, fullName: found.fullName, hospitalId: found.hospitalId, mobileNumber: found.mobileNumber };
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') foundUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'System Root' };
    }

    if (foundUser) {
      storageService.setCurrentUser(foundUser);
      setUser(foundUser);
      if (gateParams && foundUser.role === 'MR') {
        setView('GATE_ENTRY');
      } else {
        setView('DASHBOARD');
      }
      showFeedback(`Welcome back, ${foundUser.fullName}`);
    } else {
      showFeedback("Invalid credentials.", 'error');
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); setMobile(phone); setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'GATE_ENTRY' && gateParams && user) {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <GateEntryView 
          hospitalId={gateParams.hospitalId} 
          gateId={gateParams.gateId} 
          user={user} 
          onClose={() => {
            const url = new URL(window.location.href);
            url.search = '';
            window.history.replaceState({}, '', url.toString());
            setGateParams(null);
            setView('DASHBOARD');
          }} 
        />
        {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
      </FeedbackContext.Provider>
    );
  }

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
              {gateParams && (
                <div className="mt-4 bg-emerald-50 border border-emerald-100 p-3 rounded-xl flex items-center gap-2 text-left animate-pulse">
                  <Scan className="h-5 w-5 text-emerald-600 shrink-0" />
                  <p className="text-[10px] font-bold text-emerald-800 uppercase leading-tight">Permanent Gate QR Detected. Login to verify your pass.</p>
                </div>
              )}
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">Demo Shortcuts</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center"><User className="h-3 w-3 mb-1" /> MR John</button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center"><ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin</button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'User ID' : 'Mobile/ID'}</label>
                  <input type="text" value={mobile} onChange={e => setMobile(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-white/10 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20">
                <HospitalIcon className="h-3.5 w-3.5 text-indigo-100" />
                <span className="text-xs font-black text-white tracking-tighter">MedPass Technology</span>
              </div>
            </div>
          </div>
          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); }} 
        title={user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, QrCode, Sun, Moon, Maximize, Search, PlusCircle, UserCircle, Scan, Info
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })));
    setAiInsight(insight);
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Already applied today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { refreshData(); setLoading(false); showFeedback("Applied successfully!"); }, 600);
  };

  const handleSimulateScan = (hId: string) => {
    // In a real app, this would open a camera. 
    // Here we simulate the URL hit that scanning the permanent QR would trigger.
    const url = new URL(window.location.href);
    url.searchParams.set('hospital_id', hId);
    url.searchParams.set('gate_id', 'G1-MAIN');
    window.location.href = url.toString();
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> Profile</button>
      </div>

      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm">
        <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
        <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Calculating your ranking..."}</p>
      </div>

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Facilities
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group relative">
                  <div className="flex justify-between items-start mb-4">
                    <p className="font-black text-slate-800 text-lg">{h.name}</p>
                    <button 
                      onClick={() => handleSimulateScan(h.id)}
                      className="p-3 bg-emerald-600 text-white rounded-2xl shadow-lg hover:bg-emerald-700 active:scale-95 transition-all flex flex-col items-center gap-1 text-[8px] font-black uppercase"
                    >
                      <Scan className="h-4 w-4" />
                      Scan Gate
                    </button>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => (
                      <div key={sess} className="space-y-1">
                        <button
                          disabled={loading}
                          onClick={() => handleApply(h.id, sess)}
                          className="w-full py-3 px-4 bg-white border border-slate-200 hover:border-indigo-400 rounded-xl text-xs font-black flex items-center justify-between transition-all"
                        >
                          <span className="flex items-center gap-2">
                            {sess === 'MORNING' ? <Sun className="h-4 w-4 text-amber-500" /> : <Moon className="h-4 w-4 text-indigo-400" />}
                            {sess}
                          </span>
                          <PlusCircle className="h-4 w-4 text-indigo-600" />
                        </button>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest px-1">Window: {h.sessionWindows?.[sess]?.start} - {h.sessionWindows?.[sess]?.end}</p>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <QrCode className="h-5 w-5 text-indigo-500" /> Today's Passes
            </h3>
            <div className="space-y-4">
              {passes.filter(p => p.entryStatus === 'NOT_USED' && p.passDate === new Date().toISOString().split('T')[0]).map(p => (
                <div key={p.id} className="p-5 bg-indigo-50 border-2 border-indigo-100 rounded-[2rem] shadow-sm">
                  <div className="flex justify-between items-center mb-3">
                    <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                    <span className="text-[10px] font-black text-slate-400">{p.id}</span>
                  </div>
                  <p className="font-bold text-slate-800 text-sm mb-4">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                  <div className="bg-white p-4 rounded-2xl flex flex-col items-center gap-3 border border-indigo-100">
                    <div className="bg-slate-50 p-3 rounded-xl border border-dashed border-slate-200 flex flex-col items-center text-center">
                       <Scan className="h-10 w-10 text-slate-300 mb-2" />
                       <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-tight">Scan Permanent Hospital QR<br/>to Verify Entry</p>
                    </div>
                  </div>
                </div>
              ))}
              {passes.filter(p => p.entryStatus === 'NOT_USED' && p.passDate === new Date().toISOString().split('T')[0]).length === 0 && (
                <div className="text-center py-16 text-slate-400 italic text-xs border border-dashed border-slate-200 rounded-3xl">
                  No active passes for today.
                </div>
              )}
            </div>
          </section>
        </div>
      )}

      {activeTab === 'directory' && (
