import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, ShieldCheck, Mail, Phone, Briefcase, 
  CheckCircle2, Eye, Zap, Timer, HelpCircle, History, Search, MapPin, ExternalLink
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'settings'>('lottery');
  const [brief, setBrief] = useState('');

  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(storageService.getMRs()); 
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setLogs(storageService.getLogs());
    setApprovals(storageService.getApprovals());

    if (currentHosp && !editingHospital) setEditingHospital({ ...currentHosp });
    const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
    setBrief(summary);
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { refreshData(); }, [refreshData]);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) { showFeedback(result.message); refreshData(); }
    else showFeedback(result.message, 'error');
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    showFeedback("Settings saved.");
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);
  if (!currentHospital || !editingHospital) return <div className="p-20 text-center font-bold">Loading...</div>;

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const filteredPasses = passes
    .filter(p => p.hospitalId === user.hospitalId)
    .filter(p => {
      const mr = mrs.find(m => m.id === p.mrId);
      const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
      const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
      return matchesSearch && matchesSession;
    })
    .sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4">
        <Sparkles className="h-6 w-6 text-indigo-200" />
        <p className="text-sm font-medium">{brief || "Analyzing booking patterns..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><History className="h-4 w-4" /> Audit Logs</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-red-500 text-[8px] flex items-center justify-center text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('settings')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Settings className="h-4 w-4" /> Configure</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
           <h3 className="text-xl font-bold mb-8">Daily Selection Control</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
             {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => {
               if (!currentHospital.supportedSessions.includes(sess)) return null;
               const today = new Date().toISOString().split('T')[0];
               const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
               const isRun = apps.some(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted'));
               return (
                 <div key={sess} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col justify-between">
                    <div>
                      <div className="flex justify-between items-center mb-4">
                        <p className="font-black uppercase tracking-widest text-indigo-600 text-[10px]">{sess.replace('_', ' ')}</p>
                        <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${isRun ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>{isRun ? 'COMPLETED' : 'PENDING'}</span>
                      </div>
                      <p className="text-3xl font-black text-slate-800 mb-1">{count}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-6">Applicants Today</p>
                    </div>
                    <button 
                      disabled={count === 0 || isRun}
                      onClick={() => handleManualLottery(sess)}
                      className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg disabled:opacity-30 disabled:grayscale transition-all active:scale-95"
                    >
                      EXECUTE SELECTION
                    </button>
                 </div>
               );
             })}
           </div>
        </section>
      )}

      {activeTab === 'history' && (
        <section className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
           <div className="p-8 border-b border-slate-50 flex justify-between items-center">
             <h3 className="text-xl font-bold">Gate Entry Audit</h3>
             <div className="flex gap-4">
                <input type="text" placeholder="Search entries..." value={historySearch} onChange={e => setHistorySearch(e.target.value)} className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" />
                <select value={historySessionFilter} onChange={e => setHistorySessionFilter(e.target.value as any)} className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-black uppercase">
                   <option value="ALL">All Sessions</option>
                   <option value="MORNING">Morning</option>
                   <option value="EVENING">Evening</option>
                   <option value="FULL_DAY">Full Day</option>
                </select>
             </div>
           </div>
           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead>
                    <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                       <th className="px-6 py-4">Date / Session</th>
                       <th className="px-6 py-4">MR Identity</th>
                       <th className="px-6 py-4">Gate Used</th>
                       <th className="px-6 py-4">Entry Status</th>
                       <th className="px-6 py-4">Validation Time</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                   {filteredPasses.map(p => {
                     const mr = mrs.find(m => m.id === p.mrId);
                     return (
                       <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                          <td className="px-6 py-4">
                             <p className="text-xs font-black text-slate-800">{p.passDate}</p>
                             <p className="text-[9px] font-bold text-slate-400 uppercase">{p.session}</p>
                          </td>
                          <td className="px-6 py-4">
                             <p className="text-xs font-black text-slate-800">{mr?.fullName || 'N/A'}</p>
                             <p className="text-[10px] font-bold text-indigo-500 uppercase">{mr?.companyName}</p>
                          </td>
                          <td className="px-6 py-4">
                             <span className="text-[10px] font-black text-slate-600 bg-slate-100 px-2 py-1 rounded-lg border border-slate-200">
                               {p.entryGateId || '--'}
                             </span>
                          </td>
                          <td className="px-6 py-4">
                             <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${p.entryStatus === 'USED' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                               {p.entryStatus === 'USED' ? 'CHECKED-IN' : 'PENDING'}
                             </span>
                          </td>
                          <td className="px-6 py-4">
                             <p className="text-xs font-bold text-slate-700">{p.entryTime ? new Date(p.entryTime).toLocaleTimeString() : '--'}</p>
                          </td>
                       </tr>
                     );
                   })}
                 </tbody>
              </table>
           </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
           <h3 className="text-xl font-bold mb-8">Facility Configuration</h3>
           <div className="space-y-6">
              {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => (
                <div key={sess} className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                   <div className="flex justify-between items-center mb-4">
                      <p className="font-black uppercase tracking-widest text-slate-800 text-xs">{sess.replace('_', ' ')}</p>
                      <input type="number" value={editingHospital.passLimits?.[sess] || 0} onChange={e => setEditingHospital({...editingHospital, passLimits: {...editingHospital.passLimits, [sess]: parseInt(e.target.value) || 0}})} className="w-20 px-3 py-1.5 bg-white border border-slate-200 rounded-xl font-bold text-sm" />
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Entry Start</label>
                         <input type="time" value={editingHospital.sessionWindows?.[sess]?.start || '00:00'} onChange={e => setEditingHospital({...editingHospital, sessionWindows: {...editingHospital.sessionWindows, [sess]: {...editingHospital.sessionWindows?.[sess], start: e.target.value}}})} className="w-full px-4 py-2 bg-white border border-slate-200 rounded-xl font-bold text-xs" />
                      </div>
                      <div>
                         <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Entry End</label>
                         <input type="time" value={editingHospital.sessionWindows?.[sess]?.end || '23:59'} onChange={e => setEditingHospital({...editingHospital, sessionWindows: {...editingHospital.sessionWindows, [sess]: {...editingHospital.sessionWindows?.[sess], end: e.target.value}}})} className="w-full px-4 py-2 bg-white border border-slate-200 rounded-xl font-bold text-xs" />
                      </div>
                   </div>
                </div>
              ))}
              <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 transition-all uppercase tracking-widest text-sm">SAVE CHANGES</button>
           </div>
        </section>
      )}
    </div>
  );
};

