    if (!users) {
      const initial: HospitalUser[] = [
        { id: 'u1', hospitalId: 'h1', mobileNumber: '0771', password: 'admin', role: 'ADMIN', fullName: 'Colombo Admin' },
        { id: 'u2', hospitalId: 'h1', mobileNumber: '07711', password: 'guard', role: 'SECURITY', fullName: 'Colombo Security' },
      ];
      localStorage.setItem(KEYS.HOSPITAL_USERS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(users);
  },
  saveHospitalUsers: (users: HospitalUser[]) => localStorage.setItem(KEYS.HOSPITAL_USERS, JSON.stringify(users)),

  getApprovals: (): MRHospitalApproval[] => JSON.parse(localStorage.getItem(KEYS.APPROVALS) || '[]'),
  saveApprovals: (apps: MRHospitalApproval[]) => localStorage.setItem(KEYS.APPROVALS, JSON.stringify(apps)),

  getApplications: (): PassApplication[] => JSON.parse(localStorage.getItem(KEYS.APPLICATIONS) || '[]'),
  saveApplications: (apps: PassApplication[]) => localStorage.setItem(KEYS.APPLICATIONS, JSON.stringify(apps)),

  getPasses: (): IssuedPass[] => {
    const data = localStorage.getItem(KEYS.PASSES);
    if (!data) return [];
    return JSON.parse(data).map((p: any) => ({
      ...p,
      status: p.status || 'APPROVED',
      entryStatus: p.entryStatus || 'NOT_USED'
    }));
  },
  savePasses: (passes: IssuedPass[]) => localStorage.setItem(KEYS.PASSES, JSON.stringify(passes)),

  getCompanies: (): PharmaCompany[] => {
    const companies = localStorage.getItem(KEYS.COMPANIES);
    if (!companies) {
      const initial: PharmaCompany[] = [{ 
        id: 'c1', 
        name: 'Pfizer Lanka', 
        contactEmail: 'admin@pfizer.lk', 
        companyCode: 'PFIZ-01',
        adminMobile: '0779', 
        adminPassword: 'pfiz', 
        isActive: true 
      }];
      localStorage.setItem(KEYS.COMPANIES, JSON.stringify(initial));
