} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })));
    setAiInsight(insight);
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Already applied today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { refreshData(); setLoading(false); showFeedback("Applied successfully!"); }, 600);
  };

  const handleSimulateScan = (hId: string) => {
    // Permanent QR simulation via URL hit
    const url = new URL(window.location.href);
    url.searchParams.set('hospital_id', hId);
    url.searchParams.set('gate_id', 'G1-MAIN');
    window.location.href = url.toString();
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  return (
    <div className="space-y-6">
