import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import GateEntryView from './components/GateEntryView';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Laptop, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Zap, QrCode, Scan } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD' | 'GATE_ENTRY'>('LOGIN');
  const [gateParams, setGateParams] = useState<{ hospitalId: string; gateId: string } | null>(null);
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState(''); 
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    // Detect permanent QR scan from URL (e.g. ?hospital_id=h1&gate_id=1)
    const params = new URLSearchParams(window.location.search);
    const hId = params.get('hospital_id');
    const gId = params.get('gate_id');

    if (hId && gId) {
      setGateParams({ hospitalId: hId, gateId: gId });
    }

    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      if (hId && gId && session.role === 'MR') {
        setView('GATE_ENTRY');
      } else {
        setView('DASHBOARD'); 
      }
    }

    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;
        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          if (hosp.autoLotteryEnabled?.[sess] && hosp.autoLotteryTimes?.[sess] === currentTimeStr) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              lotteryService.runLottery(hosp.id, sess);
              autoRunLogs.current.add(logKey);
            }
          }
        });
      });
    }, 30000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    let foundUser: AuthUser | null = null;

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing && existing.password === password) {
        if (existing.status === 'suspended') {
          showFeedback("Account suspended.", 'error'); return;
        }
        foundUser = { 
          id: existing.id, fullName: existing.fullName, role: 'MR', 
          companyName: existing.companyName, loginId: existing.loginId, mobileNumber: existing.mobileNumber 
        };
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile && c.adminPassword === password);
      if (found) foundUser = { id: found.id, role: 'COMPANY_ADMIN', fullName: `${found.name} Admin`, companyId: found.id };
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.password === password && u.role === role);
      if (found) foundUser = { id: found.id, role: found.role, fullName: found.fullName, hospitalId: found.hospitalId, mobileNumber: found.mobileNumber };
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') foundUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'System Root' };
    }

    if (foundUser) {
      storageService.setCurrentUser(foundUser);
      setUser(foundUser);
      if (gateParams && foundUser.role === 'MR') {
        setView('GATE_ENTRY');
      } else {
        setView('DASHBOARD');
      }
      showFeedback(`Welcome back, ${foundUser.fullName}`);
    } else {
      showFeedback("Invalid credentials.", 'error');
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); setMobile(phone); setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'GATE_ENTRY' && gateParams && user) {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <GateEntryView 
          hospitalId={gateParams.hospitalId} 
          gateId={gateParams.gateId} 
          user={user} 
          onClose={() => {
            const url = new URL(window.location.href);
            url.search = '';
            window.history.replaceState({}, '', url.toString());
            setGateParams(null);
            setView('DASHBOARD');
          }} 
        />
        {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
      </FeedbackContext.Provider>
    );
  }

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
              {gateParams && (
                <div className="mt-4 bg-emerald-50 border border-emerald-100 p-3 rounded-xl flex items-center gap-2 text-left animate-pulse">
                  <Scan className="h-5 w-5 text-emerald-600 shrink-0" />
                  <p className="text-[10px] font-bold text-emerald-800 uppercase leading-tight">Permanent Gate QR Detected. Login to verify your pass.</p>
                </div>
              )}
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">Demo Shortcuts</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center"><User className="h-3 w-3 mb-1" /> MR John</button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center"><ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin</button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'User ID' : 'Mobile/ID'}</label>
                  <input type="text" value={mobile} onChange={e => setMobile(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-white/10 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20">
                <HospitalIcon className="h-3.5 w-3.5 text-indigo-100" />
                <span className="text-xs font-black text-white tracking-tighter">MedPass Technology</span>
              </div>
            </div>
          </div>
          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); }} 
        title={user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, ShieldCheck, Mail, Phone, Briefcase, 
  CheckCircle2, Eye, Zap, Timer, HelpCircle, History, Search, MapPin, ExternalLink
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'settings'>('lottery');
  const [brief, setBrief] = useState('');

  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(storageService.getMRs()); 
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setLogs(storageService.getLogs());
    setApprovals(storageService.getApprovals());

    if (currentHosp && !editingHospital) setEditingHospital({ ...currentHosp });
    const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
    setBrief(summary);
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { refreshData(); }, [refreshData]);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) { showFeedback(result.message); refreshData(); }
    else showFeedback(result.message, 'error');
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    showFeedback("Settings saved.");
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);
  if (!currentHospital || !editingHospital) return <div className="p-20 text-center font-bold">Loading...</div>;

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const filteredPasses = passes
    .filter(p => p.hospitalId === user.hospitalId)
    .filter(p => {
      const mr = mrs.find(m => m.id === p.mrId);
      const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
      const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
      return matchesSearch && matchesSession;
    })
    .sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4">
        <Sparkles className="h-6 w-6 text-indigo-200" />
        <p className="text-sm font-medium">{brief || "Analyzing booking patterns..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><History className="h-4 w-4" /> Audit Logs</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-red-500 text-[8px] flex items-center justify-center text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('settings')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Settings className="h-4 w-4" /> Configure</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
           <h3 className="text-xl font-bold mb-8">Daily Selection Control</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
             {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => {
               if (!currentHospital.supportedSessions.includes(sess)) return null;
               const today = new Date().toISOString().split('T')[0];
               const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
               const isRun = apps.some(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted'));
               return (
                 <div key={sess} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col justify-between">
                    <div>
                      <div className="flex justify-between items-center mb-4">
                        <p className="font-black uppercase tracking-widest text-indigo-600 text-[10px]">{sess.replace('_', ' ')}</p>
                        <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${isRun ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>{isRun ? 'COMPLETED' : 'PENDING'}</span>
                      </div>
                      <p className="text-3xl font-black text-slate-800 mb-1">{count}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-6">Applicants Today</p>
                    </div>
                    <button 
                      disabled={count === 0 || isRun}
                      onClick={() => handleManualLottery(sess)}
                      className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg disabled:opacity-30 disabled:grayscale transition-all active:scale-95"
                    >
                      EXECUTE SELECTION
                    </button>
                 </div>
               );
             })}
           </div>
        </section>
      )}

      {activeTab === 'history' && (
        <section className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
           <div className="p-8 border-b border-slate-50 flex justify-between items-center">
             <h3 className="text-xl font-bold">Gate Entry Audit</h3>
             <div className="flex gap-4">
                <input type="text" placeholder="Search entries..." value={historySearch} onChange={e => setHistorySearch(e.target.value)} className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" />
                <select value={historySessionFilter} onChange={e => setHistorySessionFilter(e.target.value as any)} className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-black uppercase">
                   <option value="ALL">All Sessions</option>
                   <option value="MORNING">Morning</option>
                   <option value="EVENING">Evening</option>
                   <option value="FULL_DAY">Full Day</option>
                </select>
             </div>
           </div>
           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead>
                    <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                       <th className="px-6 py-4">Date / Session</th>
                       <th className="px-6 py-4">MR Identity</th>
                       <th className="px-6 py-4">Gate Used</th>
                       <th className="px-6 py-4">Entry Status</th>
                       <th className="px-6 py-4">Validation Time</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                   {filteredPasses.map(p => {
                     const mr = mrs.find(m => m.id === p.mrId);
                     return (
                       <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                          <td className="px-6 py-4">
                             <p className="text-xs font-black text-slate-800">{p.passDate}</p>
                             <p className="text-[9px] font-bold text-slate-400 uppercase">{p.session}</p>
                          </td>
                          <td className="px-6 py-4">
                             <p className="text-xs font-black text-slate-800">{mr?.fullName || 'N/A'}</p>
                             <p className="text-[10px] font-bold text-indigo-500 uppercase">{mr?.companyName}</p>
                          </td>
                          <td className="px-6 py-4">
                             <span className="text-[10px] font-black text-slate-600 bg-slate-100 px-2 py-1 rounded-lg border border-slate-200">
                               {p.entryGateId || '--'}
                             </span>
                          </td>
                          <td className="px-6 py-4">
                             <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${p.entryStatus === 'USED' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                               {p.entryStatus === 'USED' ? 'CHECKED-IN' : 'PENDING'}
                             </span>
                          </td>
                          <td className="px-6 py-4">
                             <p className="text-xs font-bold text-slate-700">{p.entryTime ? new Date(p.entryTime).toLocaleTimeString() : '--'}</p>
                          </td>
                       </tr>
                     );
                   })}
                 </tbody>
              </table>
           </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
           <h3 className="text-xl font-bold mb-8">Facility Configuration</h3>
           <div className="space-y-6">
              {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => (
                <div key={sess} className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                   <div className="flex justify-between items-center mb-4">
                      <p className="font-black uppercase tracking-widest text-slate-800 text-xs">{sess.replace('_', ' ')}</p>
                      <input type="number" value={editingHospital.passLimits?.[sess] || 0} onChange={e => setEditingHospital({...editingHospital, passLimits: {...editingHospital.passLimits, [sess]: parseInt(e.target.value) || 0}})} className="w-20 px-3 py-1.5 bg-white border border-slate-200 rounded-xl font-bold text-sm" />
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Entry Start</label>
                         <input type="time" value={editingHospital.sessionWindows?.[sess]?.start || '00:00'} onChange={e => setEditingHospital({...editingHospital, sessionWindows: {...editingHospital.sessionWindows, [sess]: {...editingHospital.sessionWindows?.[sess], start: e.target.value}}})} className="w-full px-4 py-2 bg-white border border-slate-200 rounded-xl font-bold text-xs" />
                      </div>
                      <div>
                         <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Entry End</label>
                         <input type="time" value={editingHospital.sessionWindows?.[sess]?.end || '23:59'} onChange={e => setEditingHospital({...editingHospital, sessionWindows: {...editingHospital.sessionWindows, [sess]: {...editingHospital.sessionWindows?.[sess], end: e.target.value}}})} className="w-full px-4 py-2 bg-white border border-slate-200 rounded-xl font-bold text-xs" />
                      </div>
                   </div>
                </div>
              ))}
              <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 transition-all uppercase tracking-widest text-sm">SAVE CHANGES</button>
           </div>
        </section>
      )}
    </div>
  );
};

export default AdminDashboard;
